-- ============================================================
-- Rune Tarot App -- registers this app in the shared multi-app
-- membership schema, and stores the 25 runes (24 Elder Futhark + Wyrd)
-- as rows in the EXISTING public.tarot_cards table (card_type = '룬타로'),
-- the same table color-tarot-app already uses (card_type = '컬러타로').
-- One shared table any ozma app can query for any card type.
--
-- Column reuse (existing tarot_cards columns, repurposed by plain meaning
-- fit -- these are already never shown to users raw, only used as AI
-- grounding text, in both apps):
--   card_num      -> the rune's position in the Elder Futhark sequence
--                    (1 Fehu ... 24 Othila, 25 Wyrd) -- NOT NULL on this
--                    table, this is its rune-side equivalent of "which
--                    card number in this deck"
--   name          -> rune's English name (e.g. "Fehu")
--   keyword       -> keywords
--   meaning       -> meaning
--   advice        -> upright/positive meaning
--   caution       -> reversed/shadow meaning (Wyrd, which has no separate
--                    reversed meaning, stores its "no reversal" note here)
--   mood_quote    -> mantra
--
-- New columns (no existing equivalent -- runes need these, color cards
-- don't use them, so they're simply null on every non-rune row):
--   name_ko, glyph, deity, element, remedy_magic,
--   talisman_material, talisman_engrave, talisman_carry
--
-- love/wealth/health/career/caution/advice/image_url/aroma_*/tea_*/
-- student_* are all nullable on tarot_cards and left null for rune rows
-- where a rune has no equivalent concept (e.g. no photo, so image_url
-- stays null -- the app renders a CSS medallion from `glyph` instead).
--
-- Run once in the Supabase SQL Editor. Re-running is safe: it deletes and
-- re-inserts only the card_type = '룬타로' rows, never touching any
-- other card_type.
-- ============================================================

insert into public.apps (key, name) values
  ('rune-tarot', '룬타로')
on conflict (key) do nothing;

-- 1) A handful of rune-only columns on the existing shared table.
alter table public.tarot_cards
  add column if not exists name_ko text,
  add column if not exists glyph text,
  add column if not exists deity text,
  add column if not exists element text,
  add column if not exists remedy_magic text,
  add column if not exists talisman_material text,
  add column if not exists talisman_engrave text,
  add column if not exists talisman_carry text;

-- 2) Seed the 25 runes. Re-run-safe: clears just this card_type first.
delete from public.tarot_cards where card_type = '룬타로';

insert into public.tarot_cards (
  card_type, card_num, name, name_ko, glyph, keyword, meaning, deity, element, advice, caution, remedy_magic, talisman_material, talisman_engrave, talisman_carry, mood_quote
) values
  ('룬타로', 1, 'Fehu', '페후', 'ᚠ', '번영, 수확, 성공, 부, 고진감래, 욕심, 위축, 손실', '소, 가축, 재산', '프레야 (Freya)', '불', '노력한 만큼 물질적 번영이 따라오고, 지금의 계획과 방향이 옳다는 확인을 받는 시기다. 재정적 기회가 열리고 있으니 붙잡아 움직여야 한다.', '헛된 노력이나 재정적 손실, 실망을 경고한다. 탐욕이나 낭비, 소유에 대한 불안한 집착을 돌아봐야 할 때다.', '이익을 얻는 것과 관계된다. 일시적 힘의 증가와 새로운 시작을 돕는다. 부를 이끌고 재산을 보호해주며, 목표의 성취를 돕는다.', '오크나무 조각과 황토색 마노', '금색 물감이나 금박으로 룬 문자를 또렷하게 새긴다.', '지갑이나 돈을 보관하는 상자 안에 넣어 지닌다.', '나는 흐르는 풍요를 두려움 없이 받아들인다.'),
  ('룬타로', 2, 'Uruz', '우루즈', 'ᚢ', '힘, 엽력, 용기, 정력, 운동, 집착, 무모, 분노, 폭력', '들소, 힘', '토르 (Thor)', '흙', '원초적인 힘과 회복력이 차오르는 시기이며, 용기 있게 도전하면 성장으로 이어진다. 체력과 의지를 믿고 밀어붙여도 좋다.', '힘의 오용, 무모함, 분노의 폭발을 경고한다. 누군가와의 힘겨루기나 건강 소진에 주의해야 한다.', '새로운 비즈니스를 시작하는 모험심과 리스크에 좋다. 건강과 웰빙을 증진하는 부적이며, 권력이나 힘을 갖는 데 좋다.', '참나무 조각과 갈색 마노', '짙은 갈색이나 검은 잉크로 굵고 힘 있게 새긴다.', '운동 가방이나 손목에 지니고 다닌다.', '나는 지치지 않는 원초적 힘으로 다시 일어선다.'),
  ('룬타로', 3, 'Thurisaz', '투리사즈', 'ᚦ', '방어, 보호, 파괴, 갈등, 유혹, 폭력, 경고', '거인, 가시, 방어', '토르 (Thor)', '불', '위험을 미리 감지하고 스스로를 지키는 방어의 시기다. 성급히 나서기보다 경계하며 상황을 지켜봐야 한다.', '갈등이나 유혹에 무방비로 노출되거나, 스스로 만든 위험에 휘말릴 수 있음을 경고한다.', '내적인 힘을 사용할 수 있게 해주며 방어와 보호, 치료를 도와준다. 자신을 더욱 강하게 해준다.', '가시나무 또는 삼나무 조각과 붉은 재스퍼', '진한 붉은색으로 날카롭게, 가시처럼 새긴다.', '현관문이나 침실 입구에 걸어둔다.', '나는 필요한 곳에 분명한 경계를 세운다.'),
  ('룬타로', 4, 'Ansuz', '앙수즈', 'ᚨ', '설교자, 웅변가, 지혜, 가르침, 소통, 오해, 속임수', '입, 웅변', '오딘 (Odin)', '바람', '지혜로운 조언이나 명료한 소통이 도착하는 시기다. 배움과 가르침을 구하기에 좋은 때다.', '오해, 왜곡된 소통, 속임수를 조심해야 한다. 전해 들은 말을 그대로 믿기보다 다시 확인해야 한다.', '시와 산문을 쓰거나 대화나 협상을 할 때 효력이 있다. 지식과 깊은 지혜, 분석 능력을 확대시킨다. 시험 합격을 도와준다.', '자작나무 조각과 라피스라줄리', '은색 펜으로 또렷하고 단정하게 새긴다.', '목걸이로 만들어 목 가까이에 지니거나 책상 위에 둔다.', '나는 필요한 지혜를 정확한 순간에 듣는다.'),
  ('룬타로', 5, 'Raidho', '라이도', 'ᚱ', '움직임, 변화, 여행, 운동, 분실, 안절부절', '전차, 여행', '토르 (Thor)', '공기', '계획된 여정과 순조로운 이동의 시기다. 목표를 향해 리듬 있게 나아가면 된다.', '방향을 잃거나 계획이 어긋나고, 분실이나 지연으로 안절부절못하게 될 수 있다.', '안정적인 여행을 보장해주며 안전하게 돌아올 수 있도록 해준다. 자신의 큰 변화를 파악하게 해주고, 법률상의 문제를 도와준다.', '물푸레나무 조각과 오렌지빛 카넬리안', '주황색 물감으로 길게 뻗은 획을 살려 새긴다.', '여행 가방이나 자동차 열쇠고리에 지닌다.', '나는 흔들림 없는 리듬으로 나아간다.'),
  ('룬타로', 6, 'Kenaz', '케나즈', 'ᚲ', '깨달음, 빛, 탐구, 이해, 재능, 비밀 유출, 상실, 발견', '불꽃, 발견', '프레야 (Freya)', '불', '어둠 속에서 빛이 비치듯 통찰과 깨달음이 찾아오는 시기다. 재능을 발휘해 새로운 것을 발견하게 된다.', '비밀이 새어나가거나 통찰이 흐려지고, 무언가를 상실할 위험이 있다.', '지식을 확장시켜주는 힘이 있다. 행운의 부적이자 공부에 열중하게 해준다. 불안과 두려움을 없애준다.', '사이프러스 나무 조각과 카넬리안', '붉은주황색으로 불꽃처럼 역동적으로 새긴다.', '작업 공간이나 책상 위, 창작 도구 곁에 둔다.', '나는 어둠 속에서도 나의 길을 밝힌다.'),
  ('룬타로', 7, 'Gebo', '게보', 'ᚷ', '선물, 교환, 사랑, 만남, 균형, 교감', '선물, 교환', '오딘 (Odin)', '공기', '대등한 관계 속에서 주고받는 사랑과 교감이 이루어지는 길한 시기다. 새로운 만남이나 계약에 좋다.', '관계가 한쪽으로 기울어 일방적인 헌신이나 부담스러운 의무가 되는 상태를 경고한다. 주고받음의 균형이 깨졌는지 점검해야 한다.', '대인관계에 도움을 준다. 사랑의 부적이자 마법의 힘을 지닌다.', '마가목 조각과 로즈쿼츠', '분홍빛 물감으로 교차하는 두 선을 정성껏 새긴다.', '두 사람이 하나씩 나누어 지니거나 함께 있는 공간에 둔다.', '나는 주고받는 균형 속에서 편안하다.'),
  ('룬타로', 8, 'Wunjo', '운조', 'ᚹ', '기쁨, 승리, 행운, 축하, 잔치, 해방, 조화', '즐거움, 희망', '오딘 (Odin)', '흙', '그동안의 노력이 결실을 맺어 기쁨과 축하의 시간이 찾아온다. 화합과 승리를 만끽해도 좋다.', '불화나 지연된 기쁨, 축하할 일이 미뤄지는 답답함을 나타낸다.', '타인에게 호의를 얻고 싶을 때 좋다. 시험 통과, 승리, 영광을 누리고 싶을 때 쓴다.', '벚나무 조각과 노란 시트린', '밝은 노란색으로 부드럽게 새긴다.', '거실이나 가족이 모이는 공간에 둔다.', '나는 지금 이 순간의 기쁨을 온전히 누린다.'),
  ('룬타로', 9, 'Hagalaz', '하갈라즈', 'ᚺ', '좌절, 고난, 장애물, 위기, 가난, 싸움, 붕괴, 타격', '눈, 파괴', '헬라 (Hela)', '물 (눈이 녹은)', '통제할 수 없는 급변이나 시련이 닥치지만, 그 안에 정화와 재건의 씨앗이 있다.', '회복이 더디고 파괴 이후의 재건이 늦어지는 상태를 나타낸다. 같은 위기가 반복되지 않도록 근본 원인을 살펴야 한다.', '집이나 건물을 보호해준다. 원하지 않는 영향을 제거해준다.', '물푸레나무 조각과 아이스블루 문스톤', '옅은 청백색으로 결정처럼 각지게 새긴다.', '변화가 필요한 공간이나 서랍 깊은 곳에 보관한다.', '나는 무너짐 뒤에 오는 새로운 질서를 신뢰한다.'),
  ('룬타로', 10, 'Nauthiz', '나우시즈', 'ᚾ', '기다림, 고통, 억제, 인재, 필요, 지연, 제한', '필요, 빈곤', '스쿨드 (Skuld)', '불', '결핍과 인내의 시간을 지나며 내면의 의지와 생존력을 단련하는 시기다.', '불필요한 고집이나 자초한 결핍으로 상황을 더 어렵게 만들고 있음을 경고한다.', '불가능하다고 생각되는 것에 성공을 거두고 싶을 때 어느 정도 도움을 준다.', '마가목 조각과 짙은 회색 스모키쿼츠', '짙은 회색이나 검은색으로 절제되게 새긴다.', '절약이 필요한 지갑이나 가계부 곁에 둔다.', '나는 부족함 속에서도 나만의 불씨를 만든다.'),
  ('룬타로', 11, 'Isa', '이사', 'ᛁ', '얼음, 동결, 정체, 정지, 지연, 차단, 냉정, 고립, 은둔', '얼음, 시작', '서리 거인', '물', '성급함을 멈추고 명료하게 상황을 지켜보는 지혜로운 정지의 시기다.', '지나친 정체와 고립, 냉담함으로 관계나 기회가 얼어붙는 상태를 경고한다.', '승진과 선거 등 권위 있는 지위를 얻고 싶을 때 효력이 있다. 마음의 안정을 돕고 고통을 감소시킨다.', '버드나무 조각과 투명 수정(클리어쿼츠)', '흰색이나 은색으로 곧게 한 획만 새긴다.', '잠들기 전 머리맡이나 명상 공간에 둔다.', '나는 멈춤 속에서 가장 또렷하게 본다.'),
  ('룬타로', 12, 'Jera', '제라', 'ᛃ', '수확, 풍요, 보상, 결과, 번영, 상승, 달성', '해(년), 수확', '프레야 (Freya)', '흙', '오랜 노력이 정직한 결실로 돌아오는 순조로운 순환의 시기다.', '결실이 지연되거나 순환의 흐름이 어긋나, 노력한 만큼 돌려받지 못하는 답답함을 나타낸다.', '무언가 기르거나 농사지을 때 좋다. 행복한 가정을 이루고 싶을 때 좋으며, 힘든 일을 쉽고 빠르게 하거나 늦춘다.', '참나무 조각과 황금빛 타이거아이', '황금빛 갈색으로 대칭을 살려 새긴다.', '씨앗을 심는 화분이나 작업 다이어리 사이에 둔다.', '나는 정직한 시간이 가져다주는 결실을 신뢰한다.'),
  ('룬타로', 13, 'Eihwaz', '에이와즈', 'ᛇ', '역경, 부활, 인내, 고통, 생존, 파괴, 고갈, 재생', '주목, 잿더미', '스카디 (Skadi)', '전부', '고통스러운 국면을 지나 마침내 재생과 부활로 이어지는 강인한 전환의 시기다.', '변화를 거부하고 낡은 것에 집착하다 고갈되거나, 회복이 지연되는 상태를 나타낸다.', '의지를 강화시킨다. 나무와 같은 생명력을 가지고 있어 건강 부적에 많이 쓰인다. 어려움을 극복하는 데 도움을 준다.', '주목나무 또는 삼나무 조각과 짙은 초록 블러드스톤', '짙은 초록이나 검정으로 뿌리처럼 깊게 새긴다.', '변화나 이별을 앞둔 시기에 몸 가까이 지닌다.', '나는 깊이 뿌리내려 어떤 변화도 견딘다.'),
  ('룬타로', 14, 'Pertho', '페르토', 'ᛈ', '운명, 승부욕, 다산, 횡재, 실수, 도박, 비밀', '제비뽑기, 운', '프리그 (Frigg)', '물', '예상치 못한 행운과 반가운 우연이 찾아오는 신비로운 시기다.', '감춰졌던 비밀이 드러나거나, 성급한 도박으로 실수와 손실을 겪을 수 있음을 경고한다.', '마법의 힘을 증가시켜준다. 내적 안정을 얻게 해준다. 기회, 인연, 운을 의미한다.', '버드나무 조각과 자수정(아메시스트)', '보랏빛으로 신비롭게, 흐릿한 경계로 새긴다.', '서랍 속 비밀스러운 자리나 일기장 사이에 보관한다.', '나는 알 수 없는 것 앞에서도 평온하다.'),
  ('룬타로', 15, 'Algiz', '알기즈', 'ᛉ', '보호, 방어, 수호, 용기, 방패, 굴복, 패배', '엘크, 보호', '발키리 (Valkyrie)', '공기', '보이지 않는 곳에서 보호받고 있으며, 직관을 믿고 나아가도 좋은 시기다.', '방어력이 무너지거나 경계가 소홀해져 위험에 노출되고, 굴복이나 패배를 경험할 수 있다.', '위험으로부터 몸을 지켜준다. 사람 또는 장소를 보호한다.', '자작나무 조각과 에메랄드 또는 초록 아벤츄린', '초록빛으로 뿔처럼 뻗은 두 획을 또렷하게 새긴다.', '현관이나 침실 입구, 자동차 안에 둔다.', '나는 보이지 않는 보호 속에서 안전하다.'),
  ('룬타로', 16, 'Sowelo', '소월로', 'ᛋ', '태양, 승리, 성공, 힘, 건강, 자신감, 풍요, 명예, 부', '태양, 번개', '발두르 (Baldur)', '공기', '목표가 명료해지고 성공과 활력이 넘치는 가장 긍정적인 시기다.', '지나친 자신감이나 자만으로 그림자를 보지 못하거나, 일시적으로 활력이 꺾인 상태를 나타낸다.', '힘을 높여준다. 완벽한 승리를 도와준다.', '물푸레나무 조각과 황수정(시트린)', '밝은 금색으로 번개처럼 힘 있게 새긴다.', '해가 잘 드는 창가나 목표를 적어둔 곳 곁에 둔다.', '나는 흔들림 없는 빛으로 목표를 비춘다.'),
  ('룬타로', 17, 'Tiwaz', '티와즈', 'ᛏ', '투지, 승리, 전투, 공격, 리더십, 굴복, 폭력, 희생', '티르, 정의', '토르 (Thor)', '공기', '정당한 노력과 원칙을 지킨 대가로 승리를 얻는 시기다. 리더십을 발휘해도 좋다.', '원칙이 무너지거나 부당한 패배, 굴복을 겪을 수 있다. 감정을 앞세운 무리한 싸움을 조심해야 한다.', '용기와 의지, 결단력을 얻을 수 있다. 승리를 돕는다. 모든 싸움에서 효과적이다.', '참나무 조각과 레드가넷', '강렬한 빨강으로 창끝처럼 곧게 새긴다.', '중요한 결정이나 경쟁을 앞둔 자리, 서류 가방에 지닌다.', '나는 옳다고 믿는 길을 흔들림 없이 지킨다.'),
  ('룬타로', 18, 'Berkana', '베르카나', 'ᛒ', '다산, 모성, 치유, 탄생, 불안, 가족 문제, 불행', '자작나무, 모성', '베르타 (Bertha)', '흙', '새로운 생명과 관계가 탄생하고, 정성껏 돌보면 순조롭게 자라나는 시기다.', '가족 문제나 불안, 성장의 지연을 겪을 수 있다. 지나친 보호나 조급함을 경계해야 한다.', '건강을 지키는 데 좋다. 혼란한 정신을 진정시켜 준다.', '자작나무 조각과 연둣빛 아벤츄린', '연둣빛 흰색으로 부드럽게 새긴다.', '육아용품 곁이나 새로운 프로젝트를 시작하는 공간에 둔다.', '나는 인내심으로 새로운 것을 키워낸다.'),
  ('룬타로', 19, 'Ehwaz', '에와즈', 'ᛖ', '협력, 파트너십, 만남, 조화, 여행, 불신, 우유부단', '말, 협력', '프레이 (Frey)', '흙', '신뢰를 바탕으로 한 협력과 순조로운 동행이 이루어지는 시기다.', '상대에 대한 불신이나 우유부단함으로 관계나 진행이 어긋날 수 있다.', '예상치 못한 원조나 좋은 결과를 받는 데 효과가 있다. 행운의 부적으로 사용되며, 사람을 모으거나 흩어지게 하는 힘이 있다.', '물푸레나무 조각과 밤색 타이거아이', '밤색으로 두 개의 대칭 선을 또렷하게 새긴다.', '함께 일하는 동료나 파트너와 나누어 지닌다.', '나는 신뢰하는 이들과 함께 나아간다.'),
  ('룬타로', 20, 'Mannaz', '만나즈', 'ᛗ', '인류애, 공동체, 협력, 결합, 사회, 고립, 편견, 우울', '인류, 공동체', '헤임달 (Heimdall)', '공기', '공동체 안에서 협력하며 자신의 자리를 찾아가는 따뜻한 연결의 시기다.', '고립감이나 편견, 우울감으로 관계에서 스스로를 소외시키고 있을 수 있다.', '사회적이고 인간적인 관계를 돕는다. 고립으로 인해 생긴 어려움을 해소시킨다.', '물푸레나무 조각과 베이지빛 페트리파이드우드', '베이지색이나 살구색으로 사람 형상을 닮게 새긴다.', '거울 옆이나 자기 성찰을 위한 공간에 둔다.', '나는 있는 그대로의 나와 타인을 이해한다.'),
  ('룬타로', 21, 'Laguz', '라구즈', 'ᛚ', '물, 바다, 감수성, 신비, 치유, 상상력, 환상, 오판', '물, 여자', '네르투스 (Nerthus)', '물', '풍부한 감수성과 직관으로 치유와 통찰을 얻는 시기다.', '환상에 빠지거나 감정에 휩쓸려 오판을 내리기 쉬운 상태를 경고한다.', '영적 능력 향상에 도움을 준다. 두려움과의 직면에서 강하게 해준다.', '버드나무 조각과 아쿠아마린', '짙은 파랑으로 물결처럼 부드럽게 새긴다.', '욕실이나 물가 가까운 공간, 잠들기 전 머리맡에 둔다.', '나는 감정을 억누르지 않고 자연스럽게 흘려보낸다.'),
  ('룬타로', 22, 'Inguz', '잉구즈', 'ᛜ', '다산, 힘, 임신, 씨앗, 가족, 평화, 성공, 성취', '풍요, 생명력', '잉그 (Ing)', '흙', '내면에 응축된 힘이 무르익어 안정적인 결실과 다산으로 이어지는 시기다.', '에너지가 정체되어 성장이 멈추거나, 준비만 하다가 기회를 놓치는 상태를 경고한다.', '타인의 존경을 받거나 높은 지위를 얻는 데 효과가 있다. 힘을 모으는 데 쓴다.', '오크나무 조각과 금색 시트린', '금색으로 마름모 모양을 정성껏 새긴다.', '침실이나 몸 가까이, 씨앗을 심는 자리에 둔다.', '나는 조급해하지 않고 내 안의 힘을 키운다.'),
  ('룬타로', 23, 'Dagaz', '다가즈', 'ᛞ', '새벽, 발전, 승리, 깨어남, 희망, 지혜, 성장', '하루, 행운', '로키 (Loki)', '불', '완전히 새로운 국면으로 도약하는 각성과 희망의 순간이다.', '변화를 눈앞에 두고도 두려움 때문에 도약을 미루거나, 깨달음의 순간을 놓치고 있을 수 있다.', '행운, 긍정적인 결과와 완성을 가져다준다. 명상을 위해 쓰인다.', '물푸레나무 조각과 선스톤', '여명의 주황빛으로 나비 날개처럼 대칭으로 새긴다.', '아침에 가장 먼저 보는 자리, 창가에 둔다.', '나는 매 순간 새로운 국면으로 깨어난다.'),
  ('룬타로', 24, 'Othila', '오씰라', 'ᛟ', '조상, 유전, 유산, 상속, 풍요, 감사, 재능', '유산, 고향, 전통', '—', '흙', '뿌리 깊은 유산과 전통 위에서 안정과 풍요를 누리는 시기다.', '가족 문제나 뿌리로부터의 단절, 유산을 둘러싼 갈등을 경고한다.', '유산, 파트너, 유대 관계 등에 좋은 영향력을 미친다.', '참나무 조각과 짙은 갈색 타이거아이', '짙은 갈색으로 가문의 문장을 새기듯 정성껏 새긴다.', '집안의 중심 공간이나 가족사진 곁에 둔다.', '나는 굳건한 뿌리 위에서 자유롭게 나아간다.'),
  ('룬타로', 25, 'Wyrd', '위르드', null, '운명, 미지, 카르마, 전적인 신뢰, 결정되지 않은 가능성', '텅 빈 서판 — 아직 쓰이지 않은 운명', '노른 세 자매 (우르드·베르단디·스쿨드)', '없음 (모든 원소를 포괄한다)', null, '위르드는 정방향과 역방향의 구분이 없다. 어느 자리에 나오든 언제나 같은 메시지를 전한다 — "이 부분은 지금 당신이 통제할 수 있는 영역 밖에 있으니, 흐름에 온전히 맡겨야 한다."', '스프레드 어디에 나오든 그 자리의 의미를 무효화하거나 증폭시키는 조커와 같은 역할을 하며, 인간의 계획을 넘어서는 더 큰 흐름을 받아들이게 돕는다.', '다듬지 않은 매끄러운 흰 돌 또는 검은 돌', '아무것도 새기지 않는다 — 문자를 새기지 않는 것 자체가 이 룬의 완성이다.', '다른 룬 부적들과 함께 주머니에 넣어 두되, 확신이 서지 않는 문제를 마주할 때만 꺼내 쥔다.', '나는 알 수 없는 것 앞에서 기꺼이 손을 놓는다.')
;

-- Everything else -- members, enrollments (role/subscription_status/
-- subscription_expires_at scoped to member_id + app_key='rune-tarot'),
-- student_codes, verification_requests -- already works for any app_key
-- with zero changes. The 4 premium categories (애정/주식/부동산/건강) are
-- gated purely on enrollments.subscription_status = 'active' for
-- app_key = 'rune-tarot' (see server.js#requireActiveSubscription).
--
-- readings (reading-history save/calendar) is NOT wired up yet in this
-- app -- draw.html and daily.html don't persist to public.readings.
